import argparse
import json
import os
import sys

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("json_file", help="JSON data file")
    parser.add_argument("command", choices=["add", "list", "remove"], help="command")
    parser.add_argument("name", nargs="?", help="bookmark name")
    parser.add_argument("url", nargs="?", help="bookmark URL")
    args = parser.parse_args()

    if not os.path.exists(args.json_file):
        print("Error: JSON file not found")
        return

    if args.command == "add":
        if not args.name or not args.url:
            print("Error: Missing name or URL")
            return
        try:
            with open(args.json_file, "r") as file:
                bookmarks = json.load(file)
        except json.JSONDecodeError:
            bookmarks = {}
        bookmarks[args.name] = args.url
        with open(args.json_file, "w") as file:
            json.dump(bookmarks, file, indent=4)
        print(f"Added {args.name} -> {args.url}")

    elif args.command == "list":
        try:
            with open(args.json_file, "r") as file:
                bookmarks = json.load(file)
        except json.JSONDecodeError:
            bookmarks = {}
        if not bookmarks:
            print("No bookmarks")
            return
        for name, url in sorted(bookmarks.items(), key=lambda item: item[0]):
            print(f"{name}\t{url}")

    elif args.command == "remove":
        try:
            with open(args.json_file, "r") as file:
                bookmarks = json.load(file)
        except json.JSONDecodeError:
            bookmarks = {}
        if args.name not in bookmarks:
            print("Error: Bookmark not found")
            return
        del bookmarks[args.name]
        with open(args.json_file, "w") as file:
            json.dump(bookmarks, file, indent=4)
        print(f"Removed {args.name}")

if __name__ == "__main__":
    main()

import sys
import argparse
import csv
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--category", help="Filter by category")
    args = parser.parse_args()
    category = args.category

    expenses = []
    for row in csv.DictReader(sys.stdin):
        expenses.append(row)

    if category:
        expenses = [row for row in expenses if row["category"] == category]

    totals = {}
    for row in expenses:
        category = row["category"]
        if category not in totals:
            totals[category] = 0.0
        totals[category] += float(row["amount"])

    totals = {category: round(total, 2) for category, total in totals.items()}

    print(json.dumps(totals, indent=4))


if __name__ == "__main__":
    main()

import sys


def main():
    board = [" " for _ in range(9)]
    current_player = "X"
    game_over = False

    while not game_over:
        print_board(board)
        move = input(f"Player {current_player}, enter your move (1-9): ")

        if move.isdigit() and 1 <= int(move) <= 9 and board[int(move) - 1] == " ":
            board[int(move) - 1] = current_player
            if check_winner(board, current_player):
                print_board(board)
                print(f"Player {current_player} wins!")
                game_over = True
            elif check_draw(board):
                print_board(board)
                print("Draw!")
                game_over = True
            else:
                current_player = "O" if current_player == "X" else "X"
        else:
            print("Invalid move. Please try again.")

def print_board(board):
    for i in range(3):
        print(" ".join(board[i * 3 : (i + 1) * 3]))
    print()

def check_winner(board, player):
    return (board[0] == board[1] == board[2] == player or
            board[3] == board[4] == board[5] == player or
            board[6] == board[7] == board[8] == player or
            board[0] == board[3] == board[6] == player or
            board[1] == board[4] == board[7] == player or
            board[2] == board[5] == board[8] == player or
            board[0] == board[4] == board[8] == player or
            board[2] == board[4] == board[6] == player)

def check_draw(board):
    return all(board[i] != " " for i in range(9))


if __name__ == "__main__":
    main()

import argparse
import json
import os

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", help="directory to inventory")
    parser.add_argument("--suffix", help="suffix to filter files by")
    args = parser.parse_args()

    inventory = inventory_directory(args.directory, args.suffix)
    print(json.dumps(inventory, indent=4))

def inventory_directory(directory, suffix=None):
    inventory = {}
    for root, dirs, files in os.walk(directory):
        for file in files:
            if suffix and not file.endswith(suffix):
                continue
            path = os.path.join(root, file)
            inventory[path] = os.path.getsize(path)
    return inventory

if __name__ == "__main__":
    main()

import argparse
import json
import sys


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=argparse.FileType("r"), help="JSONL file with transactions")
    args = parser.parse_args()

    total_cents = 0
    for line_number, line in enumerate(args.input, start=1):
        try:
            transaction = json.loads(line)
            if not isinstance(transaction, dict) or "id" not in transaction or "cents" not in transaction:
                raise ValueError("Invalid transaction format")
            if not isinstance(transaction["id"], str) or not isinstance(transaction["cents"], int):
                raise ValueError("Invalid transaction values")
            if transaction["id"] == "":
                raise ValueError("Transaction id cannot be empty")
            if transaction["cents"] <= 0:
                raise ValueError("Transaction cents must be positive")
            total_cents += transaction["cents"]
        except json.JSONDecodeError:
            print(f"Error decoding line {line_number}: {line}", file=sys.stderr)
            return 1
        except ValueError as e:
            print(f"Error in line {line_number}: {e}", file=sys.stderr)
            return 1

    print(total_cents)
    return 0


if __name__ == "__main__":
    sys.exit(main())

import json
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <json_file>")
        return

    json_file = sys.argv[1]
    try:
        with open(json_file, 'r') as file:
            data = json.load(file)
    except FileNotFoundError:
        print(f"Error: {json_file} not found")
        return

    if not isinstance(data, list) or not all(isinstance(item, dict) for item in data):
        print("Error: JSON file is not valid")
        return

    score = 0
    for item in data:
        if not all(key in item for key in ["question", "answer"]):
            print(f"Error: Question or answer missing in item {item}")
            return

        question = item["question"].strip()
        answer = item["answer"].strip().lower()

        print(question)
        for line in sys.stdin:
            user_answer = line.strip().lower()
            if user_answer == answer:
                score += 1
                break

    print(f"Score: {score}/{len(data)}")

if __name__ == "__main__":
    main()
